function majorityElementApproach2(arr) {
  /*
    T.C -> O(N)
    S.C -> O(1)
  */
  let count = 0, element = 0;
  for (let num of arr) {
    if (count === 0) {
      count = 1;
      element = num;
    } else if (num === element) {
      count++;
    } else {
      count--;
    }
  }

  let counter1 = arr.filter(num => num === element);
  if (counter1.length > Math.floor(arr.length / 2)) {
    return element;
  };
  return -1;
};

