function maximumConsecutiveOnesApproach1(arr) {
  /*
    T.C - O(N)
    S.C - O(1)
  */
  let highestOnesCount = 0, currentOnesCount = 0;
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] === 1) {
