);


function stockBuyAndSellApproach2(prices) {
  /*
    T.C -> O(N)
    S.C -> O(1)
  */
  let minPrice = Infinity, maxProfit = 0;
  for (let price of prices) {
    if (price < minPrice) {
      minPrice = price;
    } else {
      maxProfit = Math.max(maxProfit, price - minPrice)
    }
  }
  return maxProfit;
};

