function twoSumApproach1(arr, target) {
  /*
    T.C - O(N*N)
    S.C - O(1)
  */
  let ans = [-1, -1];
  for (let i = 0; i < arr.length; i++) {
    let firstNum = arr[i];
    for (let j = i + 1; j < arr.length; j++) {
