// Memoization
function fibonacciMemoization(n, memo = []) {
  if (n <= 1) return n;
  if (memo[n]) {
    return memo[n];
  }
  return (memo[n] =
    fibonacciMemoization(n - 1, memo) + fibonacciMemoization(n - 2, memo));
}

