function checkOneStringIsRotationOfAnotherApproach1(str1, str2) {
  /*
    T.C -> O(N+M),
    S.C -> O(N)
  */
  if (str1.length !== str2.length) {
    return false;
  }
  let str = str1 + str1;
  return str.includes(str2);
};

