function checkOneStringIsRotationOfAnotherApproach2(str1, str2) {
  /*
    T.C -> O(N*N),
    S.C -> O(1)
  */
  if (str1.length !== str2.length) {
    return false;
  };
  let n = str1.length;
  for (let i = 0; i < n; i++) {
    let match = true;
    for (let j = 0; j < n; j++) {
      if (str1[(i + j) % n] !== str2[j]) {
        match = false;
        break;
      }
    }
    if (match) {
      return true;
    }
  }
  return false;
};

