function reverseWordsInAGivenStringApproach2(str) {
  /*
    T.C -> O(N*N)
    S.C -> O(N)
  */
  let words = [];
  let word = "";

  for (let ch of str) {
    if (ch !== " ") {
      word += ch;
    } else if (word.length > 0) {
      words.push(word);
      word = "";
    }
  }
  if (word.length > 0) {
    words.push(word);
  }
  let start = 0, end = words.length - 1;
  while (start <= end) {
    let temp = words[start];
    words[start] = words[end];
    words[end] = temp;
    start++;
    end--;
  }
  let answer = "";
  for (let i = 0; i < words.length; i++){
    answer += words[i] + " "
  }
  return answer;
};

